  background: #2f6fdb; color: #fff; border: 0; border-radius: 7px; padding: 5px 10px;
  font: inherit; font-size: max(0.75rem, 12px); cursor: pointer;
}
.siat-btn[data-variant="ghost"] { background: rgba(255,255,255,.1); color: #e8ecf5; }
